cat > src/eywa/pattern.py <<'PY'
"""Regular-language patterns with the exact grammar from the campaign spec.

Matching is performed by a Thompson NFA whose transitions consume one Latin-1
code point.  A lazily built DFA cache makes repeated matches of the same pattern
cheap while avoiding the backtracking behavior of Python's ``re`` module.
"""


class PatternError(ValueError):
    pass


class _Parser:
    __slots__ = ("text", "pos", "length")

    def __init__(self, text):
        self.text = text
        self.pos = 0
        self.length = len(text)

    def parse(self):
        node = self.parse_union()
        if self.pos != self.length:
            raise PatternError("unexpected pattern character")
        return node

    def peek(self):
        if self.pos >= self.length:
            return None
        return self.text[self.pos]

    def parse_union(self):
        alternatives = [self.parse_sequence()]
        while self.peek() == "|":
            self.pos += 1
            alternatives.append(self.parse_sequence())
        if len(alternatives) == 1:
            return alternatives[0]
        return ("union", alternatives)

    def parse_sequence(self):
        atoms = []
        while self.pos < self.length and self.peek() not in "|)":
            atoms.append(self.parse_atom())
        return ("seq", atoms)

    def parse_atom(self):
        node = self.parse_base()
        while self.peek() == "*":
            self.pos += 1
            node = ("star", node)
        return node

    def parse_base(self):
        char = self.peek()
        if char is None:
            raise PatternError("missing atom")
        if char == "(":
            self.pos += 1
            node = self.parse_union()
            if self.peek() != ")":
                raise PatternError("missing close parenthesis")
            self.pos += 1
            return node
        if char == "[":
            return self.parse_class()
        if char == "\\":
            self.pos += 1
            if self.pos >= self.length:
                raise PatternError("trailing escape")
            char = self.text[self.pos]
            self.pos += 1
            return ("class", ((ord(char), ord(char)),))
        if char in ")]|*":
            raise PatternError("unexpected grammar symbol")
        self.pos += 1
        return ("class", ((ord(char), ord(char)),))

    def parse_class_char(self):
        if self.pos >= self.length:
            raise PatternError("unterminated character class")
        char = self.text[self.pos]
        if char == "\\":
            self.pos += 1
            if self.pos >= self.length:
                raise PatternError("trailing class escape")
            value = self.text[self.pos]
            self.pos += 1
            return value
        if char in "]-":
            raise PatternError("unescaped character class syntax")
        self.pos += 1
        return char

    def parse_class(self):
        # Current character is '['.
        self.pos += 1
        ranges = []
        while True:
            if self.pos >= self.length:
                raise PatternError("unterminated character class")
            if self.text[self.pos] == "]":
                self.pos += 1
                break
            low = self.parse_class_char()
            if self.pos < self.length and self.text[self.pos] == "-":
                self.pos += 1
                high = self.parse_class_char()
                low_code = ord(low)
                high_code = ord(high)
                if low_code > high_code:
                    raise PatternError("descending character range")
                ranges.append((low_code, high_code))
            else:
                code = ord(low)
                ranges.append((code, code))
        if not ranges:
            raise PatternError("empty character class")
        return ("class", tuple(ranges))


class Pattern:
    """A compiled full-match pattern."""

    __slots__ = ("eps", "edges", "closures", "start", "accept",
                 "_masks", "_mask_ids", "_transitions")

    def __init__(self, text):
        tree = _Parser(text).parse()
        self.eps = []
        self.edges = []
        start, accept = self._build(tree)
        self.start = start
        self.accept = accept
        self._compute_epsilon_closures()
        start_mask = self.closures[start]
        self._masks = [start_mask]
        self._mask_ids = {start_mask: 0}
        self._transitions = {}

    def _new_state(self):
        index = len(self.eps)
        self.eps.append([])
        self.edges.append([])
        return index

    def _build(self, node):
        kind = node[0]
        if kind == "class":
            start = self._new_state()
            end = self._new_state()
            for low, high in node[1]:
                self.edges[start].append((low, high, end))
            return start, end
        if kind == "seq":
            start = self._new_state()
            end = start
            for child in node[1]:
                child_start, child_end = self._build(child)
                self.eps[end].append(child_start)
                end = child_end
            return start, end
        if kind == "union":
            start = self._new_state()
            end = self._new_state()
            for child in node[1]:
                child_start, child_end = self._build(child)
                self.eps[start].append(child_start)
                self.eps[child_end].append(end)
            return start, end
        if kind == "star":
            start = self._new_state()
            end = self._new_state()
            child_start, child_end = self._build(node[1])
            self.eps[start].append(child_start)
            self.eps[start].append(end)
            self.eps[child_end].append(child_start)
            self.eps[child_end].append(end)
            return start, end
        raise PatternError("invalid pattern node")

    def _compute_epsilon_closures(self):
        count = len(self.eps)
        closures = [0] * count
        for origin in range(count):
            bits = 1 << origin
            stack = [origin]
            while stack:
                state = stack.pop()
                for target in self.eps[state]:
                    bit = 1 << target
                    if not bits & bit:
                        bits |= bit
                        stack.append(target)
            closures[origin] = bits
        self.closures = closures

    def _char_move(self, mask, code):
        """Move from an epsilon-closed NFA mask on one input code point."""
        result = 0
        pending = mask
        while pending:
            bit = pending & -pending
            state = bit.bit_length() - 1
            pending ^= bit
            for low, high, target in self.edges[state]:
                if low <= code <= high:
                    result |= self.closures[target]
        return result

    def _next_dfa(self, state_id, code):
        key = (state_id, code)
        result = self._transitions.get(key)
        if result is None:
            mask = self._char_move(self._masks[state_id], code)
            result = self._mask_ids.get(mask)
            if result is None:
                result = len(self._masks)
                self._mask_ids[mask] = result
                self._masks.append(mask)
            self._transitions[key] = result
        return result

    def fullmatch(self, value):
        state = 0
        for char in value:
            state = self._next_dfa(state, ord(char))
        return bool(self._masks[state] & (1 << self.accept))


def compile_pattern(text):
    return Pattern(text)
PY
